pm.test("201 Created (ou 409 se o grupo já existia)", () => pm.expect(pm.response.code).to.be.oneOf([201, 409]));
pm.sendRequest({ url: "http://" + pm.collectionVariables.get("iotagent") + "/iot/groups",
  header: { "fiware-service": pm.collectionVariables.get("servico"), "fiware-servicepath": pm.collectionVariables.get("caminho") } }, (err, res) => {
  const g = (res.json().groups || []).find(x => x.apikey === pm.collectionVariables.get("apikey"));
  pm.test("Grupo da apikey existe no serviço/caminho da coleção", () => pm.expect(g).to.exist);
  if (!g) return;
  pm.test("Tipo Greenhouse", () => pm.expect(g.entity_type).to.eql("Greenhouse"));
  pm.test("Recurso /iot/json", () => pm.expect(g.resource).to.eql("/iot/json"));
  if (g.cbroker) pm.test("Orion visto de dentro da rede Docker", () => pm.expect(g.cbroker).to.match(/^http:\/\/orion:1026/));
  pm.test("Dispositivos não provisionados são rejeitados", () => pm.expect(g.autoprovision).to.eql(false));
});

pm.test("201 Created (ou 409 se já existia)", () => pm.expect(pm.response.code).to.be.oneOf([201, 409]));
pm.sendRequest({ url: "http://" + pm.collectionVariables.get("iotagent") + "/iot/devices/" + pm.collectionVariables.get("device_id"),
  header: { "fiware-service": pm.collectionVariables.get("servico"), "fiware-servicepath": pm.collectionVariables.get("caminho") } }, (err, res) => {
  pm.test("Dispositivo encontrado no IoT Agent", () => pm.expect(res.code).to.eql(200));
  if (res.code !== 200) return;
  const d = res.json();
  pm.test("Mesma apikey do grupo", () => pm.expect(d.apikey).to.eql(pm.collectionVariables.get("apikey")));
  pm.test("Entidade e tipo corretos", () => { pm.expect(d.entity_name).to.eql(pm.collectionVariables.get("entidade")); pm.expect(d.entity_type).to.eql("Greenhouse"); });
  pm.test("Transporte MQTT", () => pm.expect(d.transport).to.eql("MQTT"));
  const esperados = ["temperature", "relativeHumidity", "soilMoisture", "illuminance", "relayState", "windowAngle", "samplingInterval"];
  const attrs = d.attributes || [];
  esperados.forEach(n => pm.test("Atributo " + n + " (Number, com object_id)", () => { const a = attrs.find(x => x.name === n); pm.expect(a, n).to.exist; pm.expect(a.type).to.eql("Number"); pm.expect(a.object_id, "defina o object_id de " + n).to.be.a("string").and.not.empty; }));
  pm.test("object_id diferentes entre si", () => { const ids = attrs.map(a => a.object_id); pm.expect(new Set(ids).size).to.eql(ids.length); });
  ["setRelay", "setServo", "setInterval", "setSending"].forEach(c => pm.test("Comando " + c, () => pm.expect((d.commands || []).map(x => x.name)).to.include(c)));
  const est = d.static_attributes || [];
  pm.test("Estático name (Text)", () => pm.expect(est.some(s => s.name === "name" && s.type === "Text")).to.be.true);
  pm.test("Estático location (geo:json, Point)", () => { const l = est.find(s => s.name === "location"); pm.expect(l).to.exist; pm.expect(l.type).to.eql("geo:json"); pm.expect(l.value.type).to.eql("Point"); });
});

pm.test("Status 200", () => pm.response.to.have.status(200));
const regs = pm.response.json();
pm.test("A resposta é uma lista de registros", () => pm.expect(regs).to.be.an("array").that.is.not.empty);
const r = (Array.isArray(regs) ? regs : []).find(x => ((x.dataProvided || {}).entities || []).some(e => e.id === pm.collectionVariables.get("entidade")));
pm.test("Registro da entidade da estufa", () => pm.expect(r).to.exist);
pm.test("Os 4 comandos são atendidos pelo IoT Agent", () => { pm.expect(r, "registro não encontrado").to.exist; pm.expect(r.provider.http.url).to.match(/iot-agent:4041/); pm.expect(r.dataProvided.attrs).to.include.members(["setRelay", "setServo", "setInterval", "setSending"]); });

pm.test("Status 201", () => pm.response.to.have.status(201));
const loc = pm.response.headers.get("Location") || "";
pm.test("Location com o id da subscrição", () => pm.expect(loc).to.include("/v2/subscriptions/"));
if (loc) pm.collectionVariables.set("subHistorico", loc.split("/").pop());

pm.test("Status 201", () => pm.response.to.have.status(201));
const loc = pm.response.headers.get("Location") || "";
if (loc) pm.collectionVariables.set("subAlerta", loc.split("/").pop());

