{
    "from": "now-15m",
    "to": "now",
    "queries": [
        {
            "refId": "A",
            "datasource": {
                "type": "mysql",
                "uid": "{{dsUid}}"
            },
            "rawSql": "SELECT COUNT(DISTINCT attrName) AS atributos, GROUP_CONCAT(DISTINCT attrName ORDER BY attrName) AS nomes, COUNT(*) AS linhas FROM estufa WHERE recvTime >= UTC_TIMESTAMP() - INTERVAL 30 SECOND",
            "format": "table"
        }
    ]
}

